      return `<figure class="r-person ${pose==='knocked-out'?'r-fallen':''}"><img src="${asset('assets/sprites/'+sprite+'/'+pose+'.png')}" alt="${esc(c.name)}" onerror="this.onerror=null;this.src='${asset('assets/sprites/'+sprite+'/idle.png')}'"><figcaption>${esc(id==='richard'&&sprite===D.cast.kingRichard.sprite?D.cast.kingRichard.name:c.name)}</figcaption></figure>`;
